func HandleChannelCallback(w http.ResponseWriter, r *http.Request) {
	var req CallbackReq
	_ = json.NewDecoder(r.Body).Decode(&req)
	if err := settlement.ProcessSync(r.Context(), req.NotifyID, req.OrderID); err != nil {
		http.Error(w, err.Error(), 500); return
	}
	w.WriteHeader(200)
}

func ProcessSync(ctx context.Context, notifyID, orderID string) error {
	// 1. 直接入账加余额 (无 notifyID 去重检查)
	if err := ledger.CreditOrder(ctx, orderID); err != nil { return err }
	// 2. 同步调用远端渲染发票 PDF (平均耗时 4.2s)
	return pdfClient.GenerateInvoiceSync(ctx, orderID)
}
